package solution

import (
	"reflect"
	"testing"
)

func TestMergeReplicaReadsSiblingsAndSources(t *testing.T) {
	reads := []map[string][]Version{
		{"item": {
			{Origin: "a", Counter: 1, Seen: map[string]uint64{}, Logical: 1, Value: "old"},
			{Origin: "c", Counter: 1, Seen: map[string]uint64{}, Logical: 9, Value: "independent"},
		}},
		{"item": {
			{Origin: "b", Counter: 1, Seen: map[string]uint64{"a": 1}, Logical: 3, Value: "new"},
			{Origin: "b", Counter: 1, Seen: map[string]uint64{"a": 1}, Logical: 3, Value: "new"},
		}},
	}

	got, err := MergeReplicaReads(reads, "siblings")
	if err != nil {
		t.Fatalf("MergeReplicaReads returned error: %v", err)
	}
	wantVersions := []Version{
		{Origin: "b", Counter: 1, Seen: map[string]uint64{"a": 1}, Logical: 3, Value: "new"},
		{Origin: "c", Counter: 1, Seen: map[string]uint64{}, Logical: 9, Value: "independent"},
	}
	record, ok := got["item"]
	if !ok {
		t.Fatal("missing merged item")
	}
	if !reflect.DeepEqual(record.Versions, wantVersions) {
		t.Fatalf("versions = %#v, want %#v", record.Versions, wantVersions)
	}
	if !reflect.DeepEqual(record.Sources, []string{"a", "b", "c"}) {
		t.Fatalf("sources = %#v", record.Sources)
	}
}

func TestMergeReplicaReadsLatestTieBreaks(t *testing.T) {
	reads := []map[string][]Version{{"k": {
		{Origin: "a", Counter: 5, Seen: map[string]uint64{}, Logical: 10, Value: "a5"},
		{Origin: "z", Counter: 1, Seen: map[string]uint64{}, Logical: 10, Value: "z1"},
		{Origin: "z", Counter: 2, Seen: map[string]uint64{}, Logical: 10, Value: "z2"},
		{Origin: "m", Counter: 1, Seen: map[string]uint64{}, Logical: 11, Value: "highest"},
	}}}
	got, err := MergeReplicaReads(reads, "latest")
	if err != nil {
		t.Fatalf("latest merge returned error: %v", err)
	}
	versions := got["k"].Versions
	if len(versions) != 1 || versions[0].Origin != "m" || versions[0].Value != "highest" {
		t.Fatalf("latest versions = %#v", versions)
	}

	reads[0]["k"] = reads[0]["k"][:3]
	got, err = MergeReplicaReads(reads, "latest")
	if err != nil {
		t.Fatalf("tie merge returned error: %v", err)
	}
	versions = got["k"].Versions
	if len(versions) != 1 || versions[0].Origin != "z" || versions[0].Counter != 2 {
		t.Fatalf("tie-broken latest versions = %#v", versions)
	}
}

func TestMergeReplicaReadsEmptyAndErrors(t *testing.T) {
	got, err := MergeReplicaReads(nil, "siblings")
	if err != nil {
		t.Fatalf("nil reads returned error: %v", err)
	}
	if got == nil || len(got) != 0 {
		t.Fatalf("nil reads result = %#v, want non-nil empty map", got)
	}
	if _, err := MergeReplicaReads(nil, "unknown"); err == nil {
		t.Fatal("unknown mode should fail")
	}
	invalids := []Version{
		{Origin: "", Counter: 1, Seen: map[string]uint64{}},
		{Origin: "a", Counter: 0, Seen: map[string]uint64{}},
	}
	for _, invalid := range invalids {
		if _, err := MergeReplicaReads([]map[string][]Version{{"k": {invalid}}}, "siblings"); err == nil {
			t.Fatalf("invalid version %#v was accepted", invalid)
		}
	}
}

func TestMergeReplicaReadsRejectsConflictingDot(t *testing.T) {
	reads := []map[string][]Version{
		{"k": {{Origin: "a", Counter: 1, Seen: map[string]uint64{"x": 1}, Logical: 2, Value: "one"}}},
		{"k": {{Origin: "a", Counter: 1, Seen: map[string]uint64{"x": 1}, Logical: 2, Value: "different"}}},
	}
	if _, err := MergeReplicaReads(reads, "siblings"); err == nil {
		t.Fatal("same dot with different fields should be rejected")
	}
}

func TestMergeReplicaReadsDeepCopiesResult(t *testing.T) {
	seen := map[string]uint64{"ancestor": 2}
	versions := []Version{{Origin: "a", Counter: 3, Seen: seen, Logical: 4, Value: "value"}}
	read := map[string][]Version{"k": versions}
	reads := []map[string][]Version{read}

	got, err := MergeReplicaReads(reads, "siblings")
	if err != nil {
		t.Fatalf("merge returned error: %v", err)
	}
	seen["ancestor"] = 99
	versions[0].Value = "changed"
	read["k"] = nil
	reads[0] = nil

	record := got["k"]
	if len(record.Versions) != 1 || record.Versions[0].Value != "value" || record.Versions[0].Seen["ancestor"] != 2 {
		t.Fatalf("result changed after input mutation: %#v", record)
	}

	record.Versions[0].Seen["ancestor"] = 7
	record.Versions[0].Value = "result mutation"
	record.Sources[0] = "changed"
	if seen["ancestor"] != 99 || versions[0].Value != "changed" {
		t.Fatal("result aliases input storage")
	}
}

package solution

import "testing"

func TestDistinctReplicaKeysDoNotShareDots(t *testing.T) {
    reads := []map[string][]Version{{
        "a\x00b": {{Origin: "c", Counter: 1, Value: "first"}},
        "a": {{Origin: "b\x00c", Counter: 1, Value: "second"}},
    }}
    got, err := MergeReplicaReads(reads, "siblings")
    if err != nil { t.Fatalf("distinct keys and dots rejected: %v", err) }
    if len(got) != 2 { t.Fatalf("wanted two keys, got %v", got) }
}

