	}
	grouped := make(map[string][]Version)
	sourceSets := make(map[string]map[string]struct{})
	dots := make(map[string]Version)
	for _, read := range reads {
		for key, versions := range read {
			for _, v := range versions {
				if v.Origin == "" || v.Counter == 0 {
					return nil, errors.New("invalid version dot")
				}
				dot := key + "\x00" + v.Origin + "\x00" + stringCounter(v.Counter)
				if prior, ok := dots[dot]; ok {
					if !reflect.DeepEqual(prior, v) {
						return nil, errors.New("conflicting versions share a dot")
					}
					continue
				}
				dots[dot] = v
				grouped[key] = append(grouped[key], v)
				if sourceSets[key] == nil {
					sourceSets[key] = make(map[string]struct{})
				}
				sourceSets[key][v.Origin] = struct{}{}
			}
		}
	}
	out := make(map[string]MergedRecord, len(grouped))
	for key, candidates := range grouped {
		kept := make([]Version, 0, len(candidates))
		for i, candidate := range candidates {
			discard := false
			for j, other := range candidates {
				if i != j && supersedes(other, candidate) && !supersedes(candidate, other) {
					discard = true
					break
				}
			}
			if !discard {
				kept = append(kept, candidate)
			}
		}
		if mode == "latest" && len(kept) > 1 {
			winner := kept[0]
			for _, v := range kept[1:] {
				if better(v, winner) {
					winner = v
				}
			}
			kept = []Version{winner}
		}
		sort.Slice(kept, func(i, j int) bool {
			if kept[i].Origin != kept[j].Origin {
				return kept[i].Origin < kept[j].Origin
			}
			if kept[i].Counter != kept[j].Counter {
				return kept[i].Counter < kept[j].Counter
			}
			return kept[i].Value < kept[j].Value
		})
		versions := make([]Version, len(kept))
		for i, v := range kept {
			versions[i] = copyVersion(v)
		}
		sources := make([]string, 0, len(sourceSets[key]))
		for source := range sourceSets[key] {
			sources = append(sources, source)
		}
		sort.Strings(sources)
		out[key] = MergedRecord{Versions: versions, Sources: sources}
	}
	return out, nil
}

func stringCounter(n uint64) string {
	const digits = "0123456789"
	var buf [20]byte
	i := len(buf)
	for {
		i--
		buf[i] = digits[n%10]
		n /= 10
		if n == 0 {
			return string(buf[i:])
		}
	}
}
